import std/io (readFile, writeFile, println)
import std/json (decode, Json, JObject, JString, JNumber, JArray, JNull)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

export func countDots(s: string) -> int {
  countDotsHelper(s, 0, 0)
}

func countDotsHelper(s: string, index: int, count: int) -> int {
  if index >= _str_len(s)
  then count
  else {
    let c = _str_get(s, index);
    let newCount = if _str_eq(c, ".") then count + 1 else count;
    countDotsHelper(s, index + 1, newCount)
  }
}

export func validatePort(port: int) -> bool {
  port >= 1024 && port <= 65535
}

export func validateVersion(ver: string) -> bool {
  countDots(ver) == 2
}

export func findKeyInObject(kvs: List[{key: string, value: Json}], target: string) -> Json {
  match kvs {
    [] => JNull,
    kv :: rest => if _str_eq(kv.key, target) then kv.value else findKeyInObject(rest, target)
  }
}

export func extractString(json: Json) -> string {
  match json {
    JString(s) => s,
    _ => ""
  }
}

export func extractInt(json: Json) -> int {
  match json {
    JNumber(n) => floatToInt(n),
    _ => 0
  }
}

export func extractStringList(json: Json) -> List[string] {
  match json {
    JArray(items) => extractStringListHelper(items),
    _ => []
  }
}

func extractStringListHelper(items: List[Json]) -> List[string] {
  match items {
    [] => [],
    item :: rest => {
      let s = extractString(item);
      s :: extractStringListHelper(rest)
    }
  }
}

export func listLength[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    _ :: rest => 1 + listLength(rest)
  }
}

export func loadConfig(filename: string) -> Config ! {FS} {
  let content = readFile(filename);
  match decode(content) {
    Ok(JObject(kvs)) => {
      let appNameJson = findKeyInObject(kvs, "app_name");
      let versionJson = findKeyInObject(kvs, "version");
      let portJson = findKeyInObject(kvs, "port");
      let featuresJson = findKeyInObject(kvs, "features");

      let appName = extractString(appNameJson);
      let version = extractString(versionJson);
      let port = extractInt(portJson);
      let features = extractStringList(featuresJson);

      if validatePort(port) && validateVersion(version) && listLength(features) > 0
      then {
        app_name: appName,
        version: version,
        port: port,
        features: features
      }
      else {
        app_name: "DEFAULT",
        version: "0.0.0",
        port: 8080,
        features: []
      }
    },
    Ok(_) => {
      app_name: "DEFAULT",
      version: "0.0.0",
      port: 8080,
      features: []
    },
    Err(_) => {
      app_name: "DEFAULT",
      version: "0.0.0",
      port: 8080,
      features: []
    }
  }
}

export func main() -> () ! {IO, FS} {
  let configJson = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}";
  let _ = writeFile("app_config.json", configJson);

  let config = loadConfig("app_config.json");
  let numFeatures = listLength(config.features);

  let message = "Loaded " ++ config.app_name ++ " v" ++ config.version ++ " on port " ++ show(config.port) ++ " with " ++ show(numFeatures) ++ " features";
  println(message)
}

