import json
from pathlib import Path
from typing import List, TypedDict

class Config(TypedDict):
    app_name: str
    version: str
    port: int
    features: List[str]

def _validate_port(port: int) -> bool:
    return 1024 <= port <= 65535

def _validate_version(version: str) -> bool:
    return version.count(".") == 2

def load_config(filename: str) -> Config:
    config_path = Path(filename)

    if not config_path.exists():
        raise FileNotFoundError(f"Configuration file not found: {filename}")
    if not config_path.is_file():
        raise IOError(f"Path is not a file: {filename}")

    try:
        content = config_path.read_text(encoding="utf-8")
        raw_data = json.loads(content)
    except json.JSONDecodeError as e:
        raise ValueError(
            f"Error decoding JSON from {filename}: {e.msg}"
        ) from e
    except IOError as e:
        raise IOError(f"Error reading configuration file {filename}: {e}") from e

    try:
        app_name = raw_data["app_name"]
        version = raw_data["version"]
        port = raw_data["port"]
        features = raw_data["features"]
    except KeyError as e:
        raise ValueError(f"Missing required configuration field: {e}") from e

    if not isinstance(app_name, str):
        raise ValueError("Configuration error: 'app_name' must be a string.")
    if not isinstance(version, str):
        raise ValueError("Configuration error: 'version' must be a string.")
    if not isinstance(port, int):
        raise ValueError("Configuration error: 'port' must be an integer.")
    if not isinstance(features, list):
        raise ValueError("Configuration error: 'features' must be a list.")
    if not all(isinstance(feature, str) for feature in features):
        raise ValueError("Configuration error: 'features' list must contain only strings.")

    if not _validate_port(port):
        raise ValueError(
            f"Configuration error: 'port' ({port}) must be between 1024 and 65535."
        )

    if not _validate_version(version):
        raise ValueError(
            f"Configuration error: 'version' ({version}) must be in X.Y.Z format (e.g., '1.0.0')."
        )

    if not features:
        raise ValueError("Configuration error: 'features' list cannot be empty.")

    config: Config = {
        "app_name": app_name,
        "version": version,
        "port": port,
        "features": features,
    }
    return config

def main() -> None:
    config_file_name = "app_config.json"
    config_path = Path(config_file_name)

    initial_config_data = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"]
    }

    try:
        config_path.write_text(json.dumps(initial_config_data, indent=2), encoding="utf-8")

        config = load_config(config_file_name)

        num_features = len(config["features"])

        print(
            f"Loaded {config['app_name']} v{config['version']} on port {config['port']} "
            f"with {num_features} features"
        )
    except (FileNotFoundError, json.JSONDecodeError, ValueError, IOError) as e:
        print(f"Failed to load configuration: {e}")
    finally:
        if config_path.exists():
            config_path.unlink()

if __name__ == "__main__":
    main()

