func parseAge(s: string) -> Option[int] {
  match stringToInt(s) {
    Some(n) => if n > 0 then Some(n) else None,
    None => None
  }
}

func validateEmail(email: string) -> bool {
  contains(email, "@")
}

func parseRow(line: string) -> Option[Json] {
  let parts = split(line, ",") in
  match parts {
    [name, ageStr, email] => {
      match parseAge(ageStr) {
        Some(age) =>
          if validateEmail(email)
          then Some(jo([ kv("name", js(name)), kv("age", jnum(intToFloat(age))), kv("email", js(email)) ]))
          else None,
        None => None
      }
    },
    _ => None
  }
}

func collectValid(rows: List[string]) -> List[Json] {
  match rows {
    [] => [],
    x :: xs => match parseRow(x) {
      Some(j) => j :: collectValid(xs),
      None => collectValid(xs)
    }
  }
}

func count[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    _ :: rest => 1 + count(rest)
  }
}

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com" in
  let _ = writeFile("users.csv", csvContent) in

  let content = readFile("users.csv") in
  let lines = split(content, "\n") in
  -- Skip header
  let rows = match lines {
    [] => [],
    _ :: tail => tail
  } in

  let validJsons = collectValid(rows) in
  let jsonText = encode(ja(validJsons)) in
  let _ = writeFile("users.json", jsonText) in

  println("Converted " ++ show(count(validJsons)) ++ " valid rows to users.json")
}

