from typing import TypeVar, Generic, Callable

T = TypeVar('T')

class Pure(Generic[T]):
    """Wrapper for pure values - cannot contain IO effects"""
    def __init__(self, value: T):
        self._value = value

    def get(self) -> T:
        return self._value

class IO(Generic[T]):
    """Wrapper for effectful computations - can perform IO"""
    def __init__(self, effect: Callable[[], T]):
        self._effect = effect

    def run(self) -> T:
        return self._effect()

def double(x: int) -> Pure[int]:
    """Pure function: returns x * 2"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: returns a + b"""
    return Pure(a + b)

def printResult(label: str, value: int) -> IO[None]:
    """Effectful function: prints label and value"""
    def effect():
        print(f"{label}: {value}")
    return IO(effect)

def compute_and_print() -> IO[None]:
    """Effectful function: computes and prints result"""
    def effect():
        result1 = double(5).get()
        result2 = add(result1, 3).get()
        printResult("Result", result2).run()
    return IO(effect)

if __name__ == "__main__":
    compute_and_print().run()

