from dataclasses import dataclass
from typing import TypeVar, Generic, Union

T = TypeVar('T')

@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T

@dataclass(frozen=True)
class Err:
    message: str

Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main():
    # Test Case 1: parse_int("10") then divide by 2 -> "Result: 5"
    parse_result_1 = parse_int("10")
    if isinstance(parse_result_1, Ok):
        divide_result_1 = divide_safe(parse_result_1.value, 2)
        if isinstance(divide_result_1, Ok):
            print(f"Result: {divide_result_1.value}")
        else:
            print(f"Error: {divide_result_1.message}")
    else:
        print(f"Error: {parse_result_1.message}")

    # Test Case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    parse_result_2 = parse_int("10")
    if isinstance(parse_result_2, Ok):
        divide_result_2 = divide_safe(parse_result_2.value, 0)
        if isinstance(divide_result_2, Ok):
            print(f"Result: {divide_result_2.value}")
        else:
            print(f"Error: {divide_result_2.message}")
    else:
        print(f"Error: {parse_result_2.message}")

    # Test Case 3: parse_int("abc") -> "Error: Invalid integer"
    parse_result_3 = parse_int("abc")
    if isinstance(parse_result_3, Ok):
        # This branch will not be executed for "abc"
        # If it were Ok, we'd proceed to division, e.g., by 2
        divide_result_3 = divide_safe(parse_result_3.value, 2)
        if isinstance(divide_result_3, Ok):
            print(f"Result: {divide_result_3.value}")
        else:
            print(f"Error: {divide_result_3.message}")
    else:
        print(f"Error: {parse_result_3.message}")

if __name__ == "__main__":
    main()

