-- List Helper Functions (as std/list functions not explicitly provided in basic AILANG reference)

func map[a, b](f: a -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    x :: rest => f(x) :: map(f, rest)
  }
}

func filter[a](pred: a -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    x :: rest =>
      if pred(x)
      then x :: filter(pred, rest)
      else filter(pred, rest)
  }
}

func foldl[a, b](f: b -> a -> b, acc: b, xs: List[a]) -> b {
  match xs {
    [] => acc,
    x :: rest => foldl(f, f(acc, x), rest)
  }
}

func length[a](xs: List[a]) -> int {
  match xs {
    [] => 0,
    _ :: rest => 1 + length(rest)
  }
}

func contains[a](elem: a, xs: List[a]) -> bool {
  match xs {
    [] => false,
    x :: rest => if _str_eq(elem, x) then true else contains(elem, rest)
  }
}

-- Append an element to the end of a list
func append[a](xs: List[a], y: a) -> List[a] {
  match xs {
    [] => [y],
    x :: rest => x :: append(rest, y)
  }
}

-- Add to list if not already present, maintaining natural order of first appearance
func addUniqueToTail[a](elem: a, xs: List[a]) -> List[a] {
  if contains(elem, xs) then xs else append(xs, elem)
}

-- Helper to drop N elements from a list
func drop[a](n: int, xs: List[a]) -> List[a] {
  if n <= 0 then xs
  else match xs {
    [] => [],
    _ :: rest => drop(n - 1, rest)
  }
}

-- Helper to get nth element (0-indexed)
func get_nth[a](n: int, xs: List[a]) -> Option[a] {
  if n < 0 then None
  else match xs {
    [] => None,
    x :: rest => if n == 0 then Some(x) else get_nth(n - 1, rest)
  }
}

-- Helper to join list of strings with a separator
func join(xs: List[string], separator: string) -> string {
  match xs {
    [] => "",
    [x] => x,
    x :: rest => x ++ separator ++ join(rest, separator)
  }
}

-- Helper to split string by a delimiter, discarding empty strings
func non_empty_split(s: string, delim: string) -> List[string] {
  let delimLen = _str_length(delim);
  if delimLen == 0 then [s]
  else
    let rec splitter = \current_s.
      let idx = _str_indexOf(current_s, delim) in
      if idx == -1 then
        if _str_length(current_s) == 0 then [] else [current_s]
      else
        let head = _str_slice(current_s, 0, idx) in
        let tail = _str_slice(current_s, idx + delimLen, _str_length(current_s)) in
        let rest = splitter(tail) in
        if _str_length(head) == 0 then rest else head :: rest
    in splitter(s)
}

-- Helper to parse a log line
func parseLogLine(line: string) -> LogEntry {
  let parts = non_empty_split(line, " ");
  let timestamp_part_1_opt = get_nth(0, parts);
  let timestamp_part_2_opt = get_nth(1, parts);
  let level_opt = get_nth(2, parts);
  let message_parts = drop(3, parts);

  let timestamp = match timestamp_part_1_opt {
    Some(p1) => match timestamp_part_2_opt {
      Some(p2) => p1 ++ " " ++ p2,
      None => ""
    },
    None => ""
  } in
  let level = match level_opt { Some(l) => l, None => "" } in
  let message = foldl(\acc. \x. if _str_length(acc) == 0 then x else acc ++ " " ++ x, "", message_parts) in

  {
    timestamp: timestamp,
    level: level,
    message: message
  }
}

-- Helper to extract users from message
func extractUser(message: string) -> Option[string] {
  let loggedInPrefix = "User logged in: ";
  let loggedOutPrefix = "User logged out: ";

  let idxIn = _str_indexOf(message, loggedInPrefix);
  let idxOut = _str_indexOf(message, loggedOutPrefix);

  if idxIn != -1 then
    let start_idx = idxIn + _str_length(loggedInPrefix) in
    Some(_str_slice(message, start_idx, _str_length(message)))
  else if idxOut != -1 then
    let start_idx = idxOut + _str_length(loggedOutPrefix) in
    Some(_str_slice(message, start_idx, _str_length(message)))
  else
    None
}

-- Helper to calculate percentage, rounded to the nearest integer
func percentage(count: int, total: int) -> int {
  if total == 0 then 0
  else
    let val = count * 100 in
    (val + (total / 2)) / total
}

type ProcessedStats = {
  info_count: int,
  error_count: int,
  warning_count: int,
  unique_users: List[string]
}

func initialProcessedStats() -> ProcessedStats {
  { info_count: 0, error_count: 0, warning_count: 0, unique_users: [] }
}

-- Fold function to process each log entry and update statistics
func analyzeEntry(acc: ProcessedStats, entry: LogEntry) -> ProcessedStats {
  let new_info_count = if _str_eq(entry.level, "INFO") then acc.info_count + 1 else acc.info_count in
  let new_error_count = if _str_eq(entry.level, "ERROR") then acc.error_count + 1 else acc.error_count in
  let new_warning_count = if _str_eq(entry.level, "WARNING") then acc.warning_count + 1 else acc.warning_count in

  let user_opt = extractUser(entry.message) in
  let new_users = match user_opt {
    Some(user) => addUniqueToTail(user, acc.unique_users),
    None => acc.unique_users
  } in
  {
    info_count: new_info_count,
    error_count: new_error_count,
    warning_count: new_warning_count,
    unique_users: new_users
  }
