from __future__ import annotations

import argparse
import codecs
import sys
from pathlib import Path
from typing import BinaryIO, Iterable, Iterator, Optional, Sequence, Set, Tuple


def parse_args(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Count lines, words, and bytes for files and directories (wc-like). Use '-' to read from stdin."
    )
    parser.add_argument("paths", nargs="*", help="Files or directories to process; use '-' for stdin.")
    parser.add_argument(
        "-r",
        "--recursive",
        action="store_true",
        help="Recurse into directories.",
    )
    parser.add_argument(
        "-e",
        "--extensions",
        action="append",
        metavar="EXT[,EXT...]",
        help="Only include files with these extensions (e.g., -e .txt,.md). Can be used multiple times.",
    )
    parser.add_argument(
        "--include-hidden",
        action="store_true",
        help="Include hidden files and directories.",
    )
    parser.add_argument(
        "--encoding",
        default="utf-8",
        help="Text encoding used for word counting (default: utf-8).",
    )
    parser.add_argument(
        "--no-total",
        action="store_true",
        help="Do not print the total line when processing multiple inputs.",
    )
    return parser.parse_args(argv)


def normalize_extensions(values: Optional[Sequence[str]]) -> Optional[Set[str]]:
    if not values:
        return None
    exts: Set[str] = set()
    for item in values:
        for raw in item.split(","):
            ext = raw.strip().lower()
            if not ext:
                continue
            if not ext.startswith("."):
                ext = f".{ext}"
            exts.add(ext)
    return exts or None


def is_hidden_path(path: Path) -> bool:
    return any(part.startswith(".") for part in path.parts)


def iter_files_from_path(
    path: Path,
    recursive: bool,
    include_hidden: bool,
    extensions: Optional[Set[str]],
) -> Iterator[Path]:
    if path.is_file():
        if (include_hidden or not is_hidden_path(path)) and _matches_ext(path, extensions):
            yield path
        return

    if not path.is_dir():
        return

    iterator = path.rglob("*") if recursive else path.glob("*")
    for p in iterator:
        try:
            if not p.is_file():
                continue
        except OSError:
            continue
        if not include_hidden and is_hidden_path(p):
            continue
        if not _matches_ext(p, extensions):
            continue
        yield p


def _matches_ext(path: Path, extensions: Optional[Set[str]]) -> bool:
    if extensions is None:
        return True
    return path.suffix.lower() in extensions


def count_stream(stream: BinaryIO, encoding: str, chunk_size: int = 65536) -> Tuple[int, int, int]:
    decoder = codecs.getincrementaldecoder(encoding)(errors="ignore")
    bytes_count = 0
    lines = 0
    words = 0
    in_word = False

    while True:
        chunk = stream.read(chunk_size)
        if not chunk:
            break
        bytes_count += len(chunk)
        lines += chunk.count(b"\n")
        text = decoder.decode(chunk)
        for ch in text:
            if ch.isspace():
                in_word = False
            else:
                if not in_word:
                    words += 1
                    in_word = True
    remaining = decoder.decode(b"", final=True)
    for ch in remaining:
        if ch.isspace():
            in_word = False
        else:
            if not in_word:
                words += 1
                in_word = True

    return lines, words, bytes_count


def format_counts(lines: int, words: int, bytes_count: int, label: str = "") -> str:
    base = f"{lines:>12}{words:>12}{bytes_count:>12}"
    return f"{base} {label}" if label else base


def main(argv: Optional[Sequence[str]] = None) -> int:
    args = parse_args(argv)
    extensions = normalize_extensions(args.extensions)

    sources: list[Tuple[str, Optional[Path]]] = []

    if not args.paths:
        sources.append(("-", None))
    else:
        for p in args.paths:
            if p == "-":
                sources.append(("-", None))
                continue
            path = Path(p)
            if not path.exists():
                print(f"wc: {p}: No such file or directory", file=sys.stderr)
                continue
            for file_path in iter_files_from_path(path, args.recursive, args.include_hidden, extensions):
                sources.append((str(file_path), file_path))

    if not sources:
        return 1

    results: list[Tuple[int, int, int, str]] = []
    total_lines = 0
    total_words = 0
    total_bytes = 0

    for label, path in sources:
        try:
            if path is None:
                lines, words, bytes_count = count_stream(sys.stdin.buffer, args.encoding)
                display_label = "" if len(sources) == 1 else label
            else:
                with path.open("rb") as f:
                    lines, words, bytes_count = count_stream(f, args.encoding)
                display_label = label
        except Exception as exc:
            print(f"wc: {label}: {exc}", file=sys.stderr)
            continue

        results.append((lines, words, bytes_count, display_label))
        total_lines += lines
        total_words += words
        total_bytes += bytes_count

    for lines, words, bytes_count, label in results:
        print(format_counts(lines, words, bytes_count, label))

    if not args.no_total and len(results) > 1:
        print(format_counts(total_lines, total_words, total_bytes, "total"))

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

