from typing import Union

# Define State ADT
@dataclass
class Green:
    timer: int

@dataclass
class Yellow:
    timer: int

@dataclass
class Red:
    timer: int

# Union type for State
State = Union[Green, Yellow, Red]

# Define Event ADT
@dataclass
class Tick:
    pass

@dataclass
class Reset:
    pass

# Union type for Event
Event = Union[Tick, Reset]

def transition(state: State, event: Event) -> State:
    """
    Transitions the traffic light state based on the given event.
    """
    if isinstance(event, Tick):
        if isinstance(state, Green):
            return Green(state.timer - 1) if state.timer > 0 else Yellow(3)
        elif isinstance(state, Yellow):
            return Yellow(state.timer - 1) if state.timer > 0 else Red(10)
        elif isinstance(state, Red):
            return Red(state.timer - 1) if state.timer > 0 else Green(20)
    elif isinstance(event, Reset):
        return Green(20)
    # This design assumes exhaustive inputs based on State and Event types.
    # In a production system, one might raise an error for unhandled combinations.
    raise ValueError(f"Unhandled state-event combination: {state}, {event}")


def show_state(state: State) -> str:
    """
    Returns a string representation of the current traffic light state.
    """
    if isinstance(state, Green):
        return f"GREEN ({state.timer}sec)"
    elif isinstance(state, Yellow):
        return f"YELLOW ({state.timer}sec)"
    elif isinstance(state, Red):
        return f"RED ({state.timer}sec)"
    raise ValueError(f"Unknown state type: {type(state)}")


def main() -> None:
    """
    Simulates the traffic light behavior through a series of events.
    """
    current_state: State = Green(20)

    # Apply 25 Tick events
    for _ in range(25):
        current_state = transition(current_state, Tick())
        print(show_state(current_state))

    # Apply 1 Reset event
    current_state = transition(current_state, Reset())
    print(show_state(current_state))

    # Apply 5 more Tick events
    for _ in range(5):
        current_state = transition(current_state, Tick())
        print(show_state(current_state))


if __name__ == "__main__":
    main()

