type Tree =
  | Leaf(int)
  | Node(Tree, int, Tree)

func mapTree(fn: int -> int, tree: Tree) -> Tree {
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(l, v, r) => Node(mapTree(fn, l), fn(v), mapTree(fn, r))
  }
}

func foldTree(fn: int -> int -> int, acc: int, tree: Tree) -> int {
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(l, v, r) => {
      let accL = foldTree(fn, acc, l);
      let accV = fn(accL)(v);
      foldTree(fn, accV, r)
    }
  }
}

func appendList(xs: List[int], ys: List[int]) -> List[int] {
  match xs {
    [] => ys,
    x :: rest => x :: appendList(rest, ys)
  }
}

func treeToList(tree: Tree) -> List[int] {
  match tree {
    Leaf(v) => if v == 0 then [] else [v],
    Node(l, v, r) =>
      appendList(appendList(treeToList(l), [v]), treeToList(r))
  }
}

func treeDepth(tree: Tree) -> int {
  match tree {
    Leaf(_) => 1,
    Node(l, _, r) => {
      let ld = treeDepth(l);
      let rd = treeDepth(r);
      1 + (if ld > rd then ld else rd)
    }
  }
}

func restToString(xs: List[int]) -> string {
  match xs {
    [] => "]",
    x :: rest => ", " ++ show(x) ++ restToString(rest)
  }
}

func showList(lst: List[int]) -> string {
  match lst {
    [] => "[]",
    x :: rest => "[" ++ show(x) ++ restToString(rest)
  }
}

export func main() -> () ! {IO} {
  let tree = Node(
    Node(Leaf(1), 3, Leaf(0)),
    5,
    Node(Leaf(7), 8, Leaf(9))
  );

  let original = treeToList(tree);
  print("Original: " ++ showList(original));

  let doubledTree = mapTree(\x. x * 2, tree);
  let doubledList = treeToList(doubledTree);
  print("Doubled: " ++ showList(doubledList));

  let sum = foldTree(\a. \b. a + b, 0, tree);
  print("Sum: " ++ show(sum));

  let depth = treeDepth(tree);
  print("Depth: " ++ show(depth))
}

